import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
for k in G:
    print(k, len(G[k]), len(G[k][0]))

gi=G['Demo pair 1 input']; go=G['Demo pair 1 output']
for r in gi: print(''.join(str(x) if x!=6 else '.' for x in r))
print()
for r in go: print(''.join(str(x) if x!=6 else '.' for x in r))

def transform(g):
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    # find rings: colored connected components that are rectangle outlines
    import sys; sys.setrecursionlimit(10000)
    seen=[[False]*W for _ in range(H)]
    def flood(r,c,col):
        stack=[(r,c)]; comp=[]
        while stack:
            a,b=stack.pop()
            if a<0 or b<0 or a>=H or b>=W or seen[a][b] or g[a][b]!=col: continue
            seen[a][b]=True; comp.append((a,b))
            stack+=[(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
        return comp
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and not seen[r][c]:
                comp=flood(r,c,g[r][c])
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                h,w=r1-r0+1,c1-c0+1
                if h>=3 and w>=3 and len(comp)==2*h+2*w-4:
                    ih,iw=h-2,w-2
                    fill=7 if (ih*iw)%2==1 else 2
                    for i in range(r0+1,r1):
                        for j in range(c0+1,c1):
                            out[i][j]=fill
    return out
print(transform(G['Demo pair 1 input'])==G['Demo pair 1 output'])

